#nullable enable
namespace CardGame.Core.NativeOwners;
internal sealed class AdjacentDiscardAndRoundAlcoholCapability(Func<RuntimeEntries.CoreGameEngineCurrentSlashFireOffersEntries> getCoreGameEngineCurrentSlashFireOffersRuntime, Func<RuntimeEntries.CoreGameEngineAdjacentDiscardStorageEntries> getCoreGameEngineAdjacentDiscardStorageRuntime, Func<RuntimeEntries.DeferredRuntime<EngineOwners.CoreGameEngineCompletedUsePaymentsRuntime>> getCoreGameEngineCompletedUsePaymentsRuntime, Func<RuntimeEntries.CoreGameEngineRoundPricedPileAlcoholEntries> getCoreGameEngineRoundPricedPileAlcoholRuntime) : IAdjacentDiscardAndRoundAlcoholHost
{
    public SkillProgramStepOutcome OfferCurrentSlashFireAndExtraTarget(ProgramSkillFrame frame) => getCoreGameEngineCurrentSlashFireOffersRuntime().BeginCurrentSlashFireOffer(frame);
    public SkillProgramStepOutcome StoreAdjacentDiscardedSlash(ProgramSkillFrame frame, CardZoneKind zone) => getCoreGameEngineAdjacentDiscardStorageRuntime().BeginAdjacentDiscardStorage(frame, zone);
    public SkillProgramStepOutcome PayCompletedUseDiscardOrLoseHp(ProgramSkillFrame frame) => getCoreGameEngineCompletedUsePaymentsRuntime().Value.BeginCompletedUsePayment(frame);
    public SkillProgramStepOutcome UseRoundPricedPileDyingAlcohol(ProgramSkillFrame frame, string stateId, CardZoneKind zone) => getCoreGameEngineRoundPricedPileAlcoholRuntime().BeginRoundPileAlcohol(frame, stateId, zone);
}
